import { View, Text, SectionList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

// Одоогоор нөөцөд бараа алга — sections хоосон.
const SECTIONS = [];

function App() {
  // энд бичнэ үү: SectionList-д ListEmptyComponent нэмж "Илэрц алга" харуул
  return (
    <SectionList
      style={styles.screen}
      sections={SECTIONS}
      keyExtractor={(item, i) => item + i}
      renderSectionHeader={({ section }) => (
        <View testID="section-header" style={styles.header}>
          <Text style={styles.headerText}>{section.title}</Text>
        </View>
      )}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text>{item}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f8fafc" },
  header: { padding: 12, backgroundColor: "#e0e7ff" },
  headerText: { fontSize: 16, fontWeight: "bold", color: "#3730a3" },
  row: { padding: 16, backgroundColor: "#fff" },
  empty: { padding: 48, alignItems: "center" },
  emptyText: { fontSize: 18, color: "#94a3b8", fontWeight: "600" },
});

registerRootComponent(App);

